#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Always run from the repo root; values go to a gitignored .env.deploy.
cd "$(dirname "${BASH_SOURCE[0]}")/.."
ROOT=$(pwd)
ENV_FILE="$ROOT/.env.deploy"

TOTAL_STAGES=10
GCP_REGION_DEFAULT="southamerica-east1"
RUN_SERVICE="apartment-planner-api"

banner "Deploy do Apartment Planner (Supabase + Cloud Run + Cloudflare Pages)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Pré-requisitos"
say "Conferindo ferramentas locais e o seed do contrato."
missing=0
for t in uv node npx curl; do
  if command -v "$t" >/dev/null 2>&1; then step "$t ok"; else warn "$t não encontrado"; missing=1; fi
done
if ! command -v gcloud >/dev/null 2>&1; then
  warn "gcloud (Google Cloud CLI) não está instalado."
  say "Instale no WSL e rode o wizard de novo:"
  note "  curl -sSL https://sdk.cloud.google.com | bash && exec -l \$SHELL"
  open_url "https://cloud.google.com/sdk/docs/install#linux"
  missing=1
else
  step "gcloud ok"
fi
[[ -f seed/apto-166.json ]] && step "seed/apto-166.json ok" || { warn "seed/apto-166.json não encontrado"; missing=1; }
if (( missing )); then warn "Resolva os itens acima e rode de novo: scripts/deploy-wizard.sh"; exit 1; fi
note "Valores capturados ficam em .env.deploy (ignorado pelo git, modo 0600)."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Supabase: criar o projeto"
open_url "https://supabase.com/dashboard/new"
step "Crie um projeto (ex.: apartment-planner), região South America (São Paulo)."
step "Anote a senha do banco que você definir — ela vai na connection string."
step "Espere o projeto ficar pronto (~2 min)."
step "Project Settings → Data API (ou API Keys): copie a Project URL (https://xxxx.supabase.co)."
ask SUPABASE_URL "Project URL:"
SUPABASE_URL="${SUPABASE_URL%/}"
write_env SUPABASE_URL "$SUPABASE_URL"
SB_REF=$(sed -E 's#https://([^.]+)\.supabase\.co.*#\1#' <<<"$SUPABASE_URL")
open_url "https://supabase.com/dashboard/project/$SB_REF/settings/api-keys"
step "Copie a chave pública: 'Publishable key' (sb_publishable_…) ou a legacy 'anon public'."
note "Ela é pública por design (vai no frontend). NUNCA use a secret/service_role aqui."
ask SUPABASE_ANON_KEY "Publishable/anon key:"
write_env SUPABASE_ANON_KEY "$SUPABASE_ANON_KEY"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Supabase: banco e chaves JWT"
open_url "https://supabase.com/dashboard/project/$SB_REF?showConnect=true"
step "No painel 'Connect', escolha a aba/tipo 'Session pooler' (IPv4 — o Cloud Run não fala IPv6)."
step "Copie a URI (postgresql://postgres.<ref>:[YOUR-PASSWORD]@aws-…pooler.supabase.com:5432/postgres)"
step "Troque [YOUR-PASSWORD] pela senha do banco antes de colar."
note "Se a senha tiver @ : / ? # % etc., use-a URL-encoded (ex.: @ → %40) ou gere uma só com letras/números."
ask_secret DATABASE_URL "Connection string (Session pooler):"
[[ "$DATABASE_URL" == *"YOUR-PASSWORD"* ]] && { warn "Você esqueceu de trocar [YOUR-PASSWORD]."; exit 1; }
write_env DATABASE_URL "$DATABASE_URL"
open_url "https://supabase.com/dashboard/project/$SB_REF/settings/jwt"
step "Em 'JWT Signing Keys', confira que a chave em uso (Current key) é ECC (P-256) ou RSA."
note "O backend valida tokens via JWKS (ES256/RS256). Se aparecer só 'Legacy JWT secret (HS256)',"
note "clique para migrar/rotacionar para as novas signing keys antes de continuar."
pause "Chave atual é ECC/RSA? Enter para continuar"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Supabase: login só para você"
open_url "https://supabase.com/dashboard/project/$SB_REF/auth/providers"
step "Desligue 'Allow new users to sign up' (Sign In / Providers → User Signups) e salve."
step "Confira que o provider Email está habilitado."
ask OWNER_EMAIL "Seu e-mail (único usuário autorizado):"
write_env OWNER_EMAIL "$OWNER_EMAIL"
open_url "https://supabase.com/dashboard/project/$SB_REF/auth/users"
step "Add user → Create new user → e-mail: $OWNER_EMAIL, marque 'Auto Confirm User'."
note "O login é por magic link; a senha pode ser qualquer uma forte (não será usada)."
pause "Usuário criado? Enter para continuar"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Banco: migrations + carga do seu contrato"
say "Vou rodar 'alembic upgrade head' e 'import-seed' contra o Supabase."
warn "import-seed APAGA e recarrega todos os dados do app (ok agora: banco novo)."
if confirm "Rodar migrations e importar seed/apto-166.json no Supabase?"; then
  ( cd backend && export ENV=production AUTH_DISABLED=false DATABASE_URL SUPABASE_URL OWNER_EMAIL \
      && uv run alembic upgrade head \
      && uv run python -m app.cli import-seed ../seed/apto-166.json )
  step "Banco pronto."
else
  SKIPPED+=("migrations + seed no Supabase (cd backend && uv run alembic upgrade head && uv run python -m app.cli import-seed ../seed/apto-166.json)")
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare Pages: criar o projeto"
say "Vamos logar o wrangler (abre o navegador) e criar o projeto do frontend."
( cd frontend && npx --yes wrangler login )
ask PAGES_PROJECT "Nome do projeto no Pages (vira <nome>.pages.dev) [ex.: apartment-planner-lm]:"
write_env PAGES_PROJECT "$PAGES_PROJECT"
( cd frontend && npx --yes wrangler pages project create "$PAGES_PROJECT" --production-branch main ) \
  || warn "Criação falhou (nome em uso ou projeto já existe). Se já existe e é seu, siga; senão rode de novo com outro nome."
write_env PAGES_URL "https://$PAGES_PROJECT.pages.dev"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Supabase: URLs de redirecionamento do magic link"
open_url "https://supabase.com/dashboard/project/$SB_REF/auth/url-configuration"
step "Site URL: $PAGES_URL"
step "Redirect URLs: adicione  $PAGES_URL/**  e  http://localhost:4200/**"
step "Salve."
pause "Feito? Enter para continuar"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Google Cloud: projeto, faturamento e APIs"
say "Login no gcloud (abre o navegador; no WSL pode mostrar um link para colar)."
gcloud auth login --update-adc=false
ask GCP_PROJECT_ID "ID do projeto GCP (existente ou novo, ex.: apartment-planner-lm):"
write_env GCP_PROJECT_ID "$GCP_PROJECT_ID"
if ! gcloud projects describe "$GCP_PROJECT_ID" >/dev/null 2>&1; then
  if confirm "Projeto não existe. Criar '$GCP_PROJECT_ID'?"; then
    gcloud projects create "$GCP_PROJECT_ID" --name="Apartment Planner"
  else
    warn "Sem projeto não há deploy."; exit 1
  fi
fi
gcloud config set project "$GCP_PROJECT_ID" >/dev/null
ask GCP_REGION "Região do Cloud Run [Enter = $GCP_REGION_DEFAULT (São Paulo)]:"
GCP_REGION="${GCP_REGION:-$GCP_REGION_DEFAULT}"
write_env GCP_REGION "$GCP_REGION"
open_url "https://console.cloud.google.com/billing/linkedaccount?project=$GCP_PROJECT_ID"
step "Vincule uma conta de faturamento (obrigatório para Cloud Run, mesmo no free tier)."
pause "Faturamento vinculado? Enter para continuar"
open_url "https://console.cloud.google.com/billing/budgets?project=$GCP_PROJECT_ID"
step "Recomendado: crie um orçamento (ex.: R\$ 10/mês) com alertas em 50/90/100%."
pause
say "Habilitando APIs (Run, Cloud Build, Artifact Registry, Secret Manager)…"
gcloud services enable run.googleapis.com cloudbuild.googleapis.com \
  artifactregistry.googleapis.com secretmanager.googleapis.com --project "$GCP_PROJECT_ID"
step "APIs habilitadas."
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Cloud Run: deploy do backend"
PROJECT_NUMBER=$(gcloud projects describe "$GCP_PROJECT_ID" --format='value(projectNumber)')
RUN_SA="${PROJECT_NUMBER}-compute@developer.gserviceaccount.com"
say "Guardando DATABASE_URL no Secret Manager (secret 'database-url')…"
if gcloud secrets describe database-url --project "$GCP_PROJECT_ID" >/dev/null 2>&1; then
  printf '%s' "$DATABASE_URL" | gcloud secrets versions add database-url --data-file=- --project "$GCP_PROJECT_ID" >/dev/null
else
  printf '%s' "$DATABASE_URL" | gcloud secrets create database-url --data-file=- --replication-policy=automatic --project "$GCP_PROJECT_ID" >/dev/null
fi
gcloud secrets add-iam-policy-binding database-url --project "$GCP_PROJECT_ID" \
  --member="serviceAccount:$RUN_SA" --role=roles/secretmanager.secretAccessor >/dev/null
gcloud projects add-iam-policy-binding "$GCP_PROJECT_ID" \
  --member="serviceAccount:$RUN_SA" --role=roles/run.builder --condition=None >/dev/null 2>&1 \
  || note "(não consegui conceder roles/run.builder; se o build falhar por permissão, conceda-o à $RUN_SA)"
step "Secret pronto."
if confirm "Fazer o deploy de backend/ como '$RUN_SERVICE' em $GCP_REGION (público, validado por JWT)?"; then
  gcloud run deploy "$RUN_SERVICE" --source backend --region "$GCP_REGION" --project "$GCP_PROJECT_ID" \
    --allow-unauthenticated --max-instances 2 --memory 512Mi \
    --set-env-vars "ENV=production,AUTH_DISABLED=false,SUPABASE_URL=$SUPABASE_URL,OWNER_EMAIL=$OWNER_EMAIL,CORS_ORIGINS=$PAGES_URL" \
    --set-secrets "DATABASE_URL=database-url:latest" --quiet
  API_URL=$(gcloud run services describe "$RUN_SERVICE" --region "$GCP_REGION" --project "$GCP_PROJECT_ID" --format='value(status.url)')
  write_env API_URL "$API_URL"
  say "Health check:"
  curl -fsS "$API_URL/api/health" && printf '\n' || warn "health falhou — veja os logs: gcloud run services logs read $RUN_SERVICE --region $GCP_REGION"
  code=$(curl -s -o /dev/null -w '%{http_code}' "$API_URL/api/dashboard")
  [[ "$code" == "401" || "$code" == "403" ]] && step "Sem token → $code (protegido ✓)" || warn "Esperava 401/403 sem token, veio $code"
else
  warn "Sem backend o frontend não funciona."; exit 1
fi
pause

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Cloudflare Pages: build e deploy do frontend"
say "Gerando frontend/src/environments/environment.production.ts com valores públicos:"
cat > frontend/src/environments/environment.production.ts <<EOF
export const environment = {
  useMock: false,
  authDisabled: false,
  apiUrl: '$API_URL/api',
  supabaseUrl: '$SUPABASE_URL',
  supabaseAnonKey: '$SUPABASE_ANON_KEY',
};
EOF
note "  apiUrl=$API_URL/api"
( cd frontend && npx ng build --configuration production )
DIST=$(dirname "$(find frontend/dist -name index.html -path '*browser*' | head -n1)")
[[ -n "$DIST" && -f "$DIST/index.html" ]] || { warn "Build sem index.html em frontend/dist"; exit 1; }
( npx --yes wrangler pages deploy "$DIST" --project-name "$PAGES_PROJECT" --branch main --commit-dirty=true )
step "Publicado em $PAGES_URL"
open_url "$PAGES_URL"
step "Entre com $OWNER_EMAIL, abra o link do e-mail e confira o painel:"
note "  pago R\$ 10.744,00 · próximos: Corretagem 4/6 15/11 e ITBI 30/11"
note "  No celular: abra $PAGES_URL e use 'Adicionar à tela inicial'."
pause "Tudo certo? Enter para finalizar"

finish
note "Redeploy do backend: gcloud run deploy $RUN_SERVICE --source backend --region $GCP_REGION"
note "Redeploy do frontend: cd frontend && npx ng build && npx wrangler pages deploy <dist> --project-name $PAGES_PROJECT --branch main"
note "environment.production.ts mudou (só valores públicos): pode commitar."
}

run_wizard "$@"; exit
